const VisaMasterCardIcon = ({ width = "62", height = "23" }) => {
    // Generate random IDs for pattern and image
    const randomPatternId = `pattern_${Math.random().toString(36).substring(2, 10)}`;
    const randomImageId = `image_${Math.random().toString(36).substring(2, 10)}`;
    
    return (
        <svg width={width} height={height} viewBox="0 0 62 23" fill="none" xmlns="http://www.w3.org/2000/svg" xmlnsXlink="http://www.w3.org/1999/xlink">
            <rect x="0.898438" y="0.609375" width="60.8401" height="21.68" fill={`url(#${randomPatternId})`} />
            <defs>
                <pattern id={randomPatternId} patternContentUnits="objectBoundingBox" width="1" height="1">
                    <use xlinkHref={`#${randomImageId}`} transform="matrix(0.00122114 0 0 0.00342686 -0.573851 -0.200359)" />
                </pattern>
                <image id={randomImageId} width="1607" height="406" preserveAspectRatio="none" xlinkHref="data:image/jpeg;base64," />
            </defs>
        </svg>
    )
};

export default VisaMasterCardIcon;